package com.doornextdoor;

import net.runelite.api.gameval.ObjectID;

/**
 * Barrows tunnel door facts. The tunnels have 16 doorways, A to P, each a pair of leaves (left and right).
 * Each leaf is a multiloc: its impostor is the unlocked, locked or inactive door, chosen by the player's
 * own door varbits, so every player gets their own layout.
 */
final class BarrowsDoors
{
	/** The crypts and the tunnels. */
	static final int UNDERGROUND_REGION = 14231;
	/** The mounds above ground. */
	static final int SURFACE_REGION = 14131;
	static final int DOORWAYS = 16;

	enum State
	{
		UNLOCKED,
		LOCKED,
		/** Any other impostor, such as the inactive door, or no impostor at all. */
		OTHER,
	}

	private BarrowsDoors()
	{
	}

	/** Doorway index, 0 for A to 15 for P, from either leaf's ID; -1 if it isn't a tunnel door leaf. */
	static int doorway(int objectId)
	{
		if (objectId >= ObjectID.BARROWS_DOOR_A_R && objectId <= ObjectID.BARROWS_DOOR_P_R)
		{
			return objectId - ObjectID.BARROWS_DOOR_A_R;
		}
		if (objectId >= ObjectID.BARROWS_DOOR_A_L && objectId <= ObjectID.BARROWS_DOOR_P_L)
		{
			return objectId - ObjectID.BARROWS_DOOR_A_L;
		}
		return -1;
	}

	static char name(int doorway)
	{
		return (char) ('A' + doorway);
	}

	/** State from the impostor ID the leaf currently shows (-1 for none counts as OTHER). */
	static State state(int impostorId)
	{
		if (impostorId == ObjectID.BARROWS_DOOR_UNLOCKED_L || impostorId == ObjectID.BARROWS_DOOR_UNLOCKED_R)
		{
			return State.UNLOCKED;
		}
		if (impostorId == ObjectID.BARROWS_DOOR_LOCKED_L || impostorId == ObjectID.BARROWS_DOOR_LOCKED_R)
		{
			return State.LOCKED;
		}
		return State.OTHER;
	}
}

package com.doornextdoor;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(DoorNextDoorConfig.GROUP)
public interface DoorNextDoorConfig extends Config
{
	String GROUP = "doornextdoor";

	@Alpha
	@ConfigItem(keyName = "doorColor", name = "Door color",
		description = "Outline color for unlocked doors you haven't been through yet", position = 1)
	default Color doorColor()
	{
		return new Color(120, 255, 160, 230);
	}

	@ConfigItem(keyName = "eachDoorSeparately", name = "Each door on its own",
		description = "Going through a door drops only that door's outline. Turn off to also drop every other door"
			+ " with the same letter, such as the one at the far end of the passage.", position = 2)
	default boolean eachDoorSeparately()
	{
		return true;
	}
}

package com.doornextdoor;

import com.google.inject.Provides;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.MenuAction;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.WallObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WallObjectDespawned;
import net.runelite.api.events.WallObjectSpawned;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "The Door Next Door",
	description = "Highlights the unlocked doors in the Barrows tunnels, and drops each one once you've been through it",
	tags = {"barrows", "doors", "tunnels", "crypt", "chest", "pvm", "highlight"}
)
public class DoorNextDoorPlugin extends Plugin
{
	// After a scene load, leaves leaving the scene are part of the load, not doors swinging open
	private static final int SETTLE_TICKS = 3;
	// A click on a door leaf lands on its tile; match it to a tracked leaf if the ID didn't say which doorway
	private static final int CLICK_MATCH_DISTANCE = 1;

	@Inject
	private Client client;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private DoorOverlay overlay;

	@Inject
	private ClientThread clientThread;

	@Getter
	private final DoorTracker tracker = new DoorTracker();

	// Client thread only
	private final Map<WorldPoint, WallObject> leaves = new HashMap<>();
	@Nullable
	private WorldPoint lastTile;
	private int settleTicks;

	@Provides
	DoorNextDoorConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DoorNextDoorConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		clientThread.invoke(() ->
		{
			if (client.getGameState() == GameState.LOGGED_IN)
			{
				scanScene();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		leaves.clear();
		tracker.clear();
		lastTile = null;
	}

	/** Leaves already loaded don't fire spawn events, so pick them up when the plugin starts. */
	private void scanScene()
	{
		WorldView wv = client.getTopLevelWorldView();
		for (Tile[] column : wv.getScene().getTiles()[wv.getPlane()])
		{
			for (Tile tile : column)
			{
				if (tile != null && tile.getWallObject() != null)
				{
					addLeaf(tile.getWallObject());
				}
			}
		}
	}

	Collection<WallObject> getLeaves()
	{
		return Collections.unmodifiableCollection(leaves.values());
	}

	/** In the Barrows tunnels: the ground floor of the region that also holds the brothers' crypts. */
	boolean inTunnels()
	{
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return false;
		}
		WorldPoint tile = player.getWorldLocation();
		return tile.getRegionID() == BarrowsDoors.UNDERGROUND_REGION && tile.getPlane() == 0;
	}

	private void addLeaf(WallObject leaf)
	{
		int doorway = BarrowsDoors.doorway(leaf.getId());
		if (doorway < 0)
		{
			return;
		}
		WorldPoint location = leaf.getWorldLocation();
		leaves.put(location, leaf);
		tracker.leaf(doorway, location, leaf.getOrientationA(), stateOf(leaf));
	}

	/** Which door this leaf shows you right now: the multiloc's impostor, picked by your door varbits. */
	private BarrowsDoors.State stateOf(WallObject leaf)
	{
		ObjectComposition definition = client.getObjectDefinition(leaf.getId());
		if (definition == null || definition.getImpostorIds() == null)
		{
			return BarrowsDoors.State.OTHER;
		}
		ObjectComposition impostor = definition.getImpostor();
		return impostor == null ? BarrowsDoors.State.OTHER : BarrowsDoors.state(impostor.getId());
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOADING)
		{
			settleTicks = SETTLE_TICKS;
			leaves.clear();
			lastTile = null;
		}
		else if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			leaves.clear();
			tracker.clear();
			lastTile = null;
		}
	}

	@Subscribe
	public void onWallObjectSpawned(WallObjectSpawned event)
	{
		addLeaf(event.getWallObject());
	}

	@Subscribe
	public void onWallObjectDespawned(WallObjectDespawned event)
	{
		WallObject leaf = event.getWallObject();
		int doorway = BarrowsDoors.doorway(leaf.getId());
		if (doorway < 0)
		{
			return;
		}
		leaves.remove(leaf.getWorldLocation(), leaf);
		// The door you clicked Open on swung open: its leaves leave the scene while it stands open
		if (settleTicks == 0 && tracker.leafGone(doorway, leaf.getWorldLocation(), client.getTickCount()))
		{
			log.debug("Opened door {}", BarrowsDoors.name(doorway));
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (settleTicks > 0)
		{
			settleTicks--;
		}
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		WorldPoint tile = player.getWorldLocation();
		int region = tile.getRegionID();
		if (region == BarrowsDoors.SURFACE_REGION)
		{
			// Back above ground: the next trip into the tunnels starts fresh
			tracker.clearRun();
		}
		if (region != BarrowsDoors.UNDERGROUND_REGION)
		{
			lastTile = null;
			return;
		}

		// Door varbits can change without the leaf respawning, so re-read every leaf's state
		for (WallObject leaf : leaves.values())
		{
			tracker.state(BarrowsDoors.doorway(leaf.getId()), stateOf(leaf));
		}

		int crossed = tracker.moved(lastTile, tile);
		if (crossed >= 0)
		{
			log.debug("Went through door {}", BarrowsDoors.name(crossed));
		}
		lastTile = tile;
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// Read-only: we note which door you chose, and never change or add menu entries
		if (!inTunnels() || !movesYou(event.getMenuAction()))
		{
			return;
		}
		WorldPoint clicked = clickedTile(event);
		int doorway = "Open".equals(event.getMenuOption()) ? clickedDoorway(event, clicked) : -1;
		if (doorway >= 0)
		{
			tracker.clickedOpen(doorway, clicked, client.getTickCount());
		}
		else
		{
			tracker.clickedElsewhere();
		}
	}

	/** Clicks that send you somewhere in the world, so they replace a door you were heading for. */
	private static boolean movesYou(MenuAction action)
	{
		String name = action.name();
		return action == MenuAction.WALK
			|| name.startsWith("GAME_OBJECT_")
			|| name.startsWith("NPC_")
			|| name.startsWith("GROUND_ITEM_")
			|| name.startsWith("PLAYER_");
	}

	/** For object clicks, param0 and param1 are the object's scene tile. */
	private WorldPoint clickedTile(MenuOptionClicked event)
	{
		WorldView wv = client.getTopLevelWorldView();
		return WorldPoint.fromScene(wv, event.getParam0(), event.getParam1(), wv.getPlane());
	}

	private int clickedDoorway(MenuOptionClicked event, WorldPoint clicked)
	{
		int doorway = BarrowsDoors.doorway(event.getId());
		if (doorway >= 0)
		{
			return doorway;
		}
		for (Map.Entry<WorldPoint, WallObject> leaf : leaves.entrySet())
		{
			if (leaf.getKey().getPlane() == clicked.getPlane() && leaf.getKey().distanceTo2D(clicked) <= CLICK_MATCH_DISTANCE)
			{
				return BarrowsDoors.doorway(leaf.getValue().getId());
			}
		}
		return -1;
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		// Looting the chest ends the run; the next run gets a new door layout
		if (event.getGroupId() == InterfaceID.BARROWS_REWARD)
		{
			tracker.clearRun();
		}
	}
}

package com.doornextdoor;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Shape;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.WallObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/** Outlines both leaves of every unlocked door you haven't been through. Outline only, no fill. Drawing only. */
class DoorOverlay extends Overlay
{
	private static final Stroke STROKE = new BasicStroke(2f);
	private static final Color NO_FILL = new Color(0, 0, 0, 0);

	private final DoorNextDoorPlugin plugin;
	private final DoorNextDoorConfig config;

	@Inject
	DoorOverlay(DoorNextDoorPlugin plugin, DoorNextDoorConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.inTunnels())
		{
			return null;
		}
		DoorTracker tracker = plugin.getTracker();
		Color color = config.doorColor();
		boolean eachDoor = config.eachDoorSeparately();
		for (WallObject leaf : plugin.getLeaves())
		{
			if (!tracker.shouldHighlight(BarrowsDoors.doorway(leaf.getId()), leaf.getWorldLocation(), eachDoor))
			{
				continue;
			}
			Shape hull = leaf.getConvexHull();
			if (hull != null)
			{
				OverlayUtil.renderPolygon(g, hull, color, NO_FILL, STROKE);
			}
		}
		return null;
	}
}

package com.doornextdoor;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import net.runelite.api.WallObject;
import net.runelite.api.coords.WorldPoint;

/**
 * What the plugin knows about each tunnel doorway this run: where its leaves are, whether it's unlocked for
 * you, and whether you've already been through it. No client calls, so it can be unit tested.
 *
 * <p>A doorway is a letter, A to P, and one letter can be more than one door: every door with that letter
 * shares the varbit that locks it. So use is kept two ways: per letter, and per door (the tiles of the leaves
 * you went through). The plugin's setting picks which one the highlight follows.
 */
final class DoorTracker
{
	/** How long after you click Open the door may take to swing: long enough to walk there across a room. */
	static final int OPEN_CLICK_TICKS = 20;
	/** Tiles from a door's edge that still count as passing through it. Running covers 2 tiles a tick. */
	static final double CROSS_REACH = 2.5;
	/** Tiles between a door's two leaves, and between a leaf and where you clicked to open it. */
	static final int SAME_DOOR = 1;
	/** A swinging leaf this close to the tile you clicked Open on is the door you clicked. */
	static final int CLICK_REACH = 2;

	private static final class Doorway
	{
		/** Leaf tile to wall orientation (WallObject bitfield: 1 west, 2 north, 4 east, 8 south). */
		final Map<WorldPoint, Integer> leaves = new HashMap<>();
		BarrowsDoors.State state = BarrowsDoors.State.OTHER;
		/** You went through a door with this letter. */
		boolean used;
		/** Leaf tiles of the doors with this letter you went through. */
		final Set<WorldPoint> usedAt = new HashSet<>();

		void use(WorldPoint tile)
		{
			used = true;
			usedAt.add(tile);
		}

		void forget()
		{
			used = false;
			usedAt.clear();
		}

		boolean usedNear(WorldPoint tile)
		{
			for (WorldPoint used : usedAt)
			{
				if (near(used, tile, SAME_DOOR))
				{
					return true;
				}
			}
			return false;
		}
	}

	private final Doorway[] doorways = new Doorway[BarrowsDoors.DOORWAYS];
	private int pendingOpen = -1;
	private int pendingOpenTick;
	@Nullable
	private WorldPoint pendingOpenTile;

	DoorTracker()
	{
		for (int i = 0; i < doorways.length; i++)
		{
			doorways[i] = new Doorway();
		}
	}

	/** A leaf of this doorway is loaded at this tile, facing this way, currently in this state. */
	void leaf(int doorway, WorldPoint tile, int orientation, BarrowsDoors.State state)
	{
		doorways[doorway].leaves.put(tile, orientation);
		state(doorway, state);
	}

	void state(int doorway, BarrowsDoors.State state)
	{
		Doorway d = doorways[doorway];
		if (state == BarrowsDoors.State.LOCKED)
		{
			// A door you went through that's now locked means the layout changed: a new run
			d.forget();
		}
		d.state = state;
	}

	BarrowsDoors.State state(int doorway)
	{
		return doorways[doorway].state;
	}

	/**
	 * Unlocked for you and you haven't been through it yet this run.
	 *
	 * @param leaf the tile of the leaf being drawn
	 * @param eachDoor true to count only the door you went through, false for every door with its letter
	 */
	boolean shouldHighlight(int doorway, WorldPoint leaf, boolean eachDoor)
	{
		Doorway d = doorways[doorway];
		return d.state == BarrowsDoors.State.UNLOCKED && !(eachDoor ? d.usedNear(leaf) : d.used);
	}

	/** You went through a door with this letter. */
	boolean isUsed(int doorway)
	{
		return doorways[doorway].used;
	}

	/** You went through the door this leaf belongs to. */
	boolean isUsed(int doorway, WorldPoint leaf)
	{
		return doorways[doorway].usedNear(leaf);
	}

	/**
	 * You clicked Open on this doorway. It only counts once the door actually swings open.
	 *
	 * @param tile the tile you clicked, or null if it isn't known
	 */
	void clickedOpen(int doorway, @Nullable WorldPoint tile, int tick)
	{
		pendingOpen = doorway;
		pendingOpenTile = tile;
		pendingOpenTick = tick;
	}

	/** You clicked something else, so you're no longer heading for the door you clicked before. */
	void clickedElsewhere()
	{
		pendingOpen = -1;
	}

	/**
	 * A leaf of this doorway left the scene outside a scene load: the door swung open. It counts as yours
	 * only if it's the door you last clicked Open on, since other players in the tunnels open doors too.
	 *
	 * @return true if this marked the doorway as used
	 */
	boolean leafGone(int doorway, WorldPoint leaf, int tick)
	{
		if (doorway != pendingOpen || tick - pendingOpenTick > OPEN_CLICK_TICKS
			|| (pendingOpenTile != null && !near(pendingOpenTile, leaf, CLICK_REACH)))
		{
			return false;
		}
		pendingOpen = -1;
		doorways[doorway].use(leaf);
		return true;
	}

	/**
	 * You moved between these tiles in one tick. If that took you across a doorway's edge, it's used.
	 *
	 * @return the doorway you went through, or -1
	 */
	int moved(@Nullable WorldPoint from, @Nullable WorldPoint to)
	{
		if (from == null || to == null || from.equals(to) || from.getPlane() != to.getPlane())
		{
			return -1;
		}
		for (int i = 0; i < doorways.length; i++)
		{
			for (Map.Entry<WorldPoint, Integer> leaf : doorways[i].leaves.entrySet())
			{
				if (crosses(leaf.getKey(), leaf.getValue(), from, to))
				{
					doorways[i].use(leaf.getKey());
					if (pendingOpen == i)
					{
						pendingOpen = -1;
					}
					return i;
				}
			}
		}
		return -1;
	}

	/** Whether a move from one tile to another passes through the wall edge of this leaf. */
	static boolean crosses(WorldPoint leaf, int orientation, WorldPoint from, WorldPoint to)
	{
		if (leaf.getPlane() != from.getPlane())
		{
			return false;
		}
		boolean alongX;
		double edge;
		switch (orientation)
		{
			case WallObjectOrientation.WEST:
				alongX = true;
				edge = leaf.getX() - 0.5;
				break;
			case WallObjectOrientation.EAST:
				alongX = true;
				edge = leaf.getX() + 0.5;
				break;
			case WallObjectOrientation.NORTH:
				alongX = false;
				edge = leaf.getY() + 0.5;
				break;
			case WallObjectOrientation.SOUTH:
				alongX = false;
				edge = leaf.getY() - 0.5;
				break;
			default:
				return false;
		}
		double fromAcross = (alongX ? from.getX() : from.getY()) - edge;
		double toAcross = (alongX ? to.getX() : to.getY()) - edge;
		if (fromAcross * toAcross > 0 || Math.abs(fromAcross) > CROSS_REACH || Math.abs(toAcross) > CROSS_REACH)
		{
			return false;
		}
		int lateral = alongX ? leaf.getY() : leaf.getX();
		int fromLateral = alongX ? from.getY() : from.getX();
		int toLateral = alongX ? to.getY() : to.getX();
		// The doorway is two leaves wide; one tile of slack covers a diagonal step into it
		return Math.abs(fromLateral - lateral) <= 1 && Math.abs(toLateral - lateral) <= 1;
	}

	/** A new run, or you left the tunnels: every door counts as not yet used. */
	void clearRun()
	{
		for (Doorway d : doorways)
		{
			d.forget();
		}
		pendingOpen = -1;
	}

	void clear()
	{
		for (int i = 0; i < doorways.length; i++)
		{
			doorways[i] = new Doorway();
		}
		pendingOpen = -1;
	}

	/** Same floor, and within this many tiles each way. */
	static boolean near(WorldPoint a, WorldPoint b, int tiles)
	{
		return a.getPlane() == b.getPlane()
			&& Math.abs(a.getX() - b.getX()) <= tiles
			&& Math.abs(a.getY() - b.getY()) <= tiles;
	}

	/** The {@link WallObject#getOrientationA()} bits for straight walls. */
	static final class WallObjectOrientation
	{
		static final int WEST = 1;
		static final int NORTH = 2;
		static final int EAST = 4;
		static final int SOUTH = 8;

		private WallObjectOrientation()
		{
		}
	}
}

package com.doornextdoor;

import static com.doornextdoor.DoorTracker.WallObjectOrientation.EAST;
import static com.doornextdoor.DoorTracker.WallObjectOrientation.NORTH;
import static com.doornextdoor.DoorTracker.WallObjectOrientation.SOUTH;
import static com.doornextdoor.DoorTracker.WallObjectOrientation.WEST;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import org.junit.Test;

public class DoorLogicTest
{
	private static final BarrowsDoors.State UNLOCKED = BarrowsDoors.State.UNLOCKED;
	private static final BarrowsDoors.State LOCKED = BarrowsDoors.State.LOCKED;

	private static WorldPoint at(int x, int y)
	{
		return new WorldPoint(x, y, 0);
	}

	/** Doorway C's leaves: on the west edge of tiles (3550, 9700) and (3550, 9701). */
	private static final WorldPoint DOOR = at(3550, 9700);
	/** The other door C, at the far end of the passage: north edge of (3556, 9710) and (3557, 9710). */
	private static final WorldPoint FAR_DOOR = at(3556, 9710);
	/** Doorway F, somewhere else. */
	private static final WorldPoint OTHER = at(3560, 9690);

	/** Doorway C: two leaves on the west edge of tiles (3550, 9700) and (3550, 9701). */
	private static DoorTracker trackerWithWestDoor(BarrowsDoors.State state)
	{
		DoorTracker tracker = new DoorTracker();
		tracker.leaf(2, at(3550, 9700), WEST, state);
		tracker.leaf(2, at(3550, 9701), WEST, state);
		return tracker;
	}

	@Test
	public void doorwayFromEitherLeaf()
	{
		assertEquals(0, BarrowsDoors.doorway(ObjectID.BARROWS_DOOR_A_R));
		assertEquals(0, BarrowsDoors.doorway(ObjectID.BARROWS_DOOR_A_L));
		assertEquals(15, BarrowsDoors.doorway(ObjectID.BARROWS_DOOR_P_R));
		assertEquals(15, BarrowsDoors.doorway(ObjectID.BARROWS_DOOR_P_L));
		assertEquals(7, BarrowsDoors.doorway(ObjectID.BARROWS_DOOR_H_L));
		assertEquals('H', BarrowsDoors.name(7));
		// The impostors themselves and neighbouring objects aren't doorways
		assertEquals(-1, BarrowsDoors.doorway(ObjectID.BARROWS_DOOR_UNLOCKED_R));
		assertEquals(-1, BarrowsDoors.doorway(ObjectID.BARROWS_DOOR_LOCKED_L));
		assertEquals(-1, BarrowsDoors.doorway(ObjectID.BARROWS_DOOR_INACTIVE_L));
		assertEquals(-1, BarrowsDoors.doorway(ObjectID.BARROWS_TORCH));
	}

	@Test
	public void stateFromImpostor()
	{
		assertEquals(UNLOCKED, BarrowsDoors.state(ObjectID.BARROWS_DOOR_UNLOCKED_L));
		assertEquals(UNLOCKED, BarrowsDoors.state(ObjectID.BARROWS_DOOR_UNLOCKED_R));
		assertEquals(LOCKED, BarrowsDoors.state(ObjectID.BARROWS_DOOR_LOCKED_L));
		assertEquals(LOCKED, BarrowsDoors.state(ObjectID.BARROWS_DOOR_LOCKED_R));
		assertEquals(BarrowsDoors.State.OTHER, BarrowsDoors.state(ObjectID.BARROWS_DOOR_INACTIVE_R));
		assertEquals(BarrowsDoors.State.OTHER, BarrowsDoors.state(-1));
	}

	@Test
	public void highlightsUnlockedOnly()
	{
		assertTrue(trackerWithWestDoor(UNLOCKED).shouldHighlight(2, DOOR, true));
		assertFalse(trackerWithWestDoor(LOCKED).shouldHighlight(2, DOOR, true));
		assertFalse(new DoorTracker().shouldHighlight(2, DOOR, true));
	}

	@Test
	public void walkingThroughUnhighlights()
	{
		DoorTracker tracker = trackerWithWestDoor(UNLOCKED);
		assertEquals(2, tracker.moved(at(3549, 9700), at(3550, 9700)));
		assertTrue(tracker.isUsed(2));
		assertFalse(tracker.shouldHighlight(2, DOOR, true));
		// It stays off after the door closes behind you and its leaves load again
		tracker.leaf(2, at(3550, 9700), WEST, UNLOCKED);
		assertFalse(tracker.shouldHighlight(2, DOOR, true));
	}

	@Test
	public void eitherDirectionAndEitherLeaf()
	{
		DoorTracker back = trackerWithWestDoor(UNLOCKED);
		assertEquals(2, back.moved(at(3550, 9701), at(3549, 9701)));
		DoorTracker running = trackerWithWestDoor(UNLOCKED);
		assertEquals(2, running.moved(at(3548, 9701), at(3550, 9701)));
		DoorTracker diagonal = trackerWithWestDoor(UNLOCKED);
		assertEquals(2, diagonal.moved(at(3549, 9699), at(3550, 9700)));
	}

	@Test
	public void movesThatDontPassThrough()
	{
		DoorTracker tracker = trackerWithWestDoor(UNLOCKED);
		// Walking up to it, along it, and past the wall line far from the doorway
		assertEquals(-1, tracker.moved(at(3547, 9700), at(3549, 9700)));
		assertEquals(-1, tracker.moved(at(3550, 9700), at(3550, 9701)));
		assertEquals(-1, tracker.moved(at(3549, 9710), at(3550, 9710)));
		assertEquals(-1, tracker.moved(at(3549, 9700), at(3549, 9700)));
		assertEquals(-1, tracker.moved(null, at(3550, 9700)));
		// Too far to be one tick's move through the door: a teleport or a scene change
		assertEquals(-1, tracker.moved(at(3540, 9700), at(3560, 9700)));
		assertTrue(tracker.shouldHighlight(2, DOOR, true));
	}

	@Test
	public void everyWallDirection()
	{
		assertTrue(DoorTracker.crosses(at(10, 10), WEST, at(9, 10), at(10, 10)));
		assertFalse(DoorTracker.crosses(at(10, 10), WEST, at(10, 10), at(11, 10)));
		assertTrue(DoorTracker.crosses(at(10, 10), EAST, at(10, 10), at(11, 10)));
		assertFalse(DoorTracker.crosses(at(10, 10), EAST, at(9, 10), at(10, 10)));
		assertTrue(DoorTracker.crosses(at(10, 10), NORTH, at(10, 10), at(10, 11)));
		assertFalse(DoorTracker.crosses(at(10, 10), NORTH, at(10, 9), at(10, 10)));
		assertTrue(DoorTracker.crosses(at(10, 10), SOUTH, at(10, 9), at(10, 10)));
		assertFalse(DoorTracker.crosses(at(10, 10), SOUTH, at(10, 10), at(10, 11)));
		// Diagonal walls aren't doors
		assertFalse(DoorTracker.crosses(at(10, 10), 16, at(9, 10), at(10, 10)));
		// Another floor
		assertFalse(DoorTracker.crosses(new WorldPoint(10, 10, 1), WEST, at(9, 10), at(10, 10)));
	}

	@Test
	public void openingTheDoorYouClicked()
	{
		DoorTracker tracker = trackerWithWestDoor(UNLOCKED);
		tracker.clickedOpen(2, DOOR, 100);
		assertTrue(tracker.leafGone(2, DOOR, 104));
		assertFalse(tracker.shouldHighlight(2, DOOR, true));
	}

	@Test
	public void someoneElsesDoorSwinging()
	{
		DoorTracker tracker = trackerWithWestDoor(UNLOCKED);
		tracker.leaf(5, OTHER, NORTH, UNLOCKED);
		// Not the door you clicked
		tracker.clickedOpen(5, OTHER, 100);
		assertFalse(tracker.leafGone(2, DOOR, 101));
		// You clicked it, then walked off somewhere else
		tracker.clickedOpen(2, DOOR, 102);
		tracker.clickedElsewhere();
		assertFalse(tracker.leafGone(2, DOOR, 103));
		// You clicked it ages ago
		tracker.clickedOpen(2, DOOR, 110);
		assertFalse(tracker.leafGone(2, DOOR, 110 + DoorTracker.OPEN_CLICK_TICKS + 1));
		assertTrue(tracker.shouldHighlight(2, DOOR, true));
		assertTrue(tracker.shouldHighlight(5, OTHER, true));
	}

	@Test
	public void clickingALockedDoorDoesNothing()
	{
		DoorTracker tracker = trackerWithWestDoor(LOCKED);
		tracker.clickedOpen(2, DOOR, 100);
		// A locked door never swings, so there's no leafGone, and it was never highlighted
		assertFalse(tracker.isUsed(2));
		assertFalse(tracker.shouldHighlight(2, DOOR, true));
	}

	@Test
	public void newLayoutBringsDoorsBack()
	{
		DoorTracker tracker = trackerWithWestDoor(UNLOCKED);
		tracker.moved(at(3549, 9700), at(3550, 9700));
		assertFalse(tracker.shouldHighlight(2, DOOR, true));
		tracker.state(2, LOCKED);
		assertFalse(tracker.isUsed(2));
		tracker.state(2, UNLOCKED);
		assertTrue(tracker.shouldHighlight(2, DOOR, true));
	}

	@Test
	public void clearRunKeepsDoorsButForgetsUse()
	{
		DoorTracker tracker = trackerWithWestDoor(UNLOCKED);
		tracker.moved(at(3549, 9700), at(3550, 9700));
		tracker.clearRun();
		assertTrue(tracker.shouldHighlight(2, DOOR, true));
		// The leaves are still known, so walking through again still counts
		assertEquals(2, tracker.moved(at(3550, 9700), at(3549, 9700)));
		tracker.clear();
		assertFalse(tracker.shouldHighlight(2, DOOR, true));
		assertEquals(-1, tracker.moved(at(3549, 9700), at(3550, 9700)));
	}

	/** Doorway C with both of its doors: the west one, and the north one at the far end of the passage. */
	private static DoorTracker trackerWithBothDoorsC()
	{
		DoorTracker tracker = trackerWithWestDoor(UNLOCKED);
		tracker.leaf(2, FAR_DOOR, NORTH, UNLOCKED);
		tracker.leaf(2, at(3557, 9710), NORTH, UNLOCKED);
		return tracker;
	}

	@Test
	public void walkingThroughOneDoorLeavesTheFarDoorLit()
	{
		DoorTracker tracker = trackerWithBothDoorsC();
		assertEquals(2, tracker.moved(at(3549, 9700), at(3550, 9700)));
		// Both leaves of the door you used go dark
		assertFalse(tracker.shouldHighlight(2, DOOR, true));
		assertFalse(tracker.shouldHighlight(2, at(3550, 9701), true));
		assertTrue(tracker.isUsed(2, at(3550, 9701)));
		// The far door with the same letter stays lit until you go through it too
		assertTrue(tracker.shouldHighlight(2, FAR_DOOR, true));
		assertFalse(tracker.isUsed(2, FAR_DOOR));
		assertEquals(2, tracker.moved(at(3557, 9710), at(3557, 9711)));
		assertFalse(tracker.shouldHighlight(2, FAR_DOOR, true));
		assertFalse(tracker.shouldHighlight(2, at(3557, 9710), true));
	}

	@Test
	public void perLetterDropsEveryDoorWithTheLetter()
	{
		DoorTracker tracker = trackerWithBothDoorsC();
		assertTrue(tracker.shouldHighlight(2, FAR_DOOR, false));
		tracker.moved(at(3549, 9700), at(3550, 9700));
		assertFalse(tracker.shouldHighlight(2, DOOR, false));
		assertFalse(tracker.shouldHighlight(2, FAR_DOOR, false));
		// The setting only changes what's drawn, so switching it back brings the far door back
		assertTrue(tracker.shouldHighlight(2, FAR_DOOR, true));
	}

	@Test
	public void openingOneDoorLeavesTheFarDoorLit()
	{
		DoorTracker tracker = trackerWithBothDoorsC();
		tracker.clickedOpen(2, at(3550, 9701), 100);
		// Someone else swings the far door C first: not the one you clicked
		assertFalse(tracker.leafGone(2, FAR_DOOR, 101));
		assertTrue(tracker.shouldHighlight(2, FAR_DOOR, true));
		// Your door swings
		assertTrue(tracker.leafGone(2, DOOR, 102));
		assertFalse(tracker.shouldHighlight(2, at(3550, 9701), true));
		assertTrue(tracker.shouldHighlight(2, FAR_DOOR, true));
	}

	@Test
	public void lockedOrNewRunForgetsEveryDoor()
	{
		DoorTracker tracker = trackerWithBothDoorsC();
		tracker.moved(at(3549, 9700), at(3550, 9700));
		tracker.state(2, LOCKED);
		tracker.state(2, UNLOCKED);
		assertTrue(tracker.shouldHighlight(2, DOOR, true));
		tracker.moved(at(3549, 9700), at(3550, 9700));
		tracker.clearRun();
		assertTrue(tracker.shouldHighlight(2, DOOR, true));
		assertTrue(tracker.shouldHighlight(2, DOOR, false));
	}
